\title{Denominators of Multiples of Points on Mordell Curves:\\
Refutation of the ``Only Bad Primes'' Conjecture,\\
Exact Residue-Class Counts, and an Information Barrier}
\author{Aristotle}
\date{15 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For the Mordell family $E_N : y^2 = x^3 + N$ over $\QQ$, with discriminant
$\Delta(E_N) = -432N^2$, it has been conjectured that the denominators of the $x$-coordinates
$x(nP)$ of multiples of an integral point $P$ are divisible only by the \emph{bad} primes of
the curve, namely $2$, $3$ and the primes dividing $N$. We refute this conjecture by an
explicit counterexample --- for $N = 55 = 5 \cdot 11$ and $P = (9,28)$ one has
$x(2P) = 2601/3136$ with $3136 = 2^6 \cdot 7^2$ and $7 \nmid \Delta$ --- and replace it by an
exact local theory. For every prime $\ell \ge 5$ of good reduction we prove
$\ell \mid \den x(2P) \iff \ell \mid y \iff x^3 + N \equiv 0 \pmod{\ell}$ and
$\ell \mid \den x(3P) \iff \ell \mid \psi_3(x) = 3x^4 + 12Nx$, the latter via the tripling
formula $x(3P) = \varphi_3(x)/\psi_3(x)^2$ and a non-cancellation lemma whose two exceptional
numerator values, $64N^3$ and $-1728N^3$, involve only the primes $2$ and $3$. We then count
the denominator-producing residue classes exactly: at layer $2$ the count is $1$ at
supersingular primes and $0$ or $3$ at ordinary primes, with total $\ell$ over the residues of
$N$; at layer $3$ it is $2$, respectively $1$ or $4$, with total $2\ell-1$. Every prime
$\ell \ge 5$ is realised as a good-reduction denominator prime by the witness $N = 1-\ell^3$,
$P = (\ell,1)$, and for every $N$ infinitely many good primes are denominator-active. Finally,
both criteria depend on $N$ only through $N \bmod \ell$; combined with Dirichlet's theorem
applied to the modulus $B!$ this yields an information barrier: for every bound $B$ and every
semiprime $N = pq$ with $p,q > B$ there is a \emph{prime} $M > N$ whose layer-2 and layer-3
denominator criteria coincide with those of $N$ at every prime $\ell \le B$. The denominator
profile below $B$ therefore cannot distinguish a semiprime from a prime, let alone recover its
factorisation.
\end{abstract}

\noindent\textbf{Keywords:} Mordell curve; elliptic curve; denominator; division polynomial;
reduction modulo $p$; cubic residues; Dirichlet's theorem; integer factorisation.

\section{Introduction}

\subsection{The setting}

Let $N$ be a nonzero integer and consider the Mordell curve
\[
E_N : y^2 = x^3 + N .
\]
As a Weierstrass equation with $a_1 = a_2 = a_3 = a_4 = 0$, $a_6 = N$, its discriminant is
\[
\Delta(E_N) = -432N^2 = -2^4 \cdot 3^3 \cdot N^2 .
\]
A prime $\ell$ is \emph{bad} for $E_N$ if $\ell \mid \Delta$, i.e.\ if $\ell \in \{2,3\}$ or
$\ell \mid N$; otherwise $\ell$ is a prime of \emph{good reduction}. The rational points form
an abelian group under the chord-and-tangent law, and for an integral point $P = (x,y)$ with
$y \neq 0$,
\begin{equation}\label{eq:double}
x(2P) = \frac{x^4 - 8Nx}{4y^2}.
\end{equation}

\subsection{The conjecture and its refutation}

\begin{conjecture}[Only Bad Primes]
For $N = pq$ a semiprime and $P$ an integral point of $E_N$, every prime dividing
$\den x(nP)$ for some $n \ge 2$ lies in $\{2,3,p,q\}$, i.e.\ divides $\Delta(E_N)$.
\end{conjecture}

If true this would make factoring $N$ trivial: compute $x(2P)$, factor its small structured
denominator, and read off $p$ and $q$. The conjecture is false, and the smallest natural
example already refutes it.

\begin{theorem}[Counterexample]\label{thm:counterexample}
Let $N = 55 = 5\cdot 11$ and $P = (9,28) \in E_{55}(\QQ)$. Then
\[
x(2P) = \frac{9^4 - 8\cdot 55 \cdot 9}{4 \cdot 28^2} = \frac{2601}{3136},
\qquad 3136 = 2^6 \cdot 7^2,
\]
and $7 \nmid \Delta(E_{55}) = -1306800 = -2^4 3^3 5^2 11^2$. Thus the prime $7$, of good
reduction, divides the denominator of $x(2P)$.
\end{theorem}

\begin{proof}
$9^4 = 6561$ and $8\cdot 55\cdot 9 = 3960$, so the numerator is $2601 = 3^2 17^2$; the
denominator is $4 \cdot 784 = 3136 = 2^6 7^2$; the two are coprime, so the fraction is in
lowest terms. Since $\Delta = -2^4 3^3 5^2 11^2$, the prime $7$ does not divide $\Delta$.
\end{proof}

\subsection{The mechanism}

A rational point whose coordinates have an $\ell$ in the denominator reduces to the point at
infinity $O$ in $E_N(\FF_\ell)$. Hence, for a good prime $\ell$,
\[
\ell \mid \den x(nP) \iff nP \equiv O \pmod \ell \iff
\text{the reduction $\bar P$ has order dividing } n .
\]
Nothing in this condition refers to $\Delta$. In the counterexample $\bar P = (2,0)$ modulo $7$
has order $2$, so $2P$ reduces to $O$ and $7$ enters the denominator. Since a point can reduce
to torsion at infinitely many primes, good primes must appear infinitely often.

\section{Notation and preliminaries}

Throughout, $N$ is a nonzero integer, $\ell$ a rational prime, and $\FF_\ell$ the field with
$\ell$ elements. For a rational $r$ in lowest terms with positive denominator, $\den r$ denotes
that denominator; $\bar x$ is the image of $x \in \ZZ$ in $\FF_\ell$. A prime $\ell \ge 5$ with
$\ell \nmid N$ is a prime of good reduction; we call it \emph{supersingular} if
$\ell \equiv 2 \pmod 3$ and \emph{ordinary} if $\ell \equiv 1 \pmod 3$. (For this family
$\ell \equiv 2 \pmod 3$ is exactly the condition that $t \mapsto t^3$ is a bijection of
$\FF_\ell$, and then $\#E_N(\FF_\ell) = \ell+1$.)

\begin{lemma}[Cubing dichotomy]\label{lem:cube}
If $\ell \equiv 2 \pmod 3$ then $t \mapsto t^3$ is a bijection of $\FF_\ell$. If
$\ell \equiv 1 \pmod 3$ then $\FF_\ell$ contains a primitive cube root of unity
$\omega \ne 1$, and $t \mapsto t^3$ is three-to-one on $\FF_\ell^\times$.
\end{lemma}

\begin{proof}[Proof sketch]
$\FF_\ell^\times$ is cyclic of order $\ell-1$. If $3 \nmid \ell-1$ then cubing is a group
automorphism and fixes $0$, hence is bijective. If $3 \mid \ell-1$, Cauchy's theorem produces
an element $\omega$ of order $3$, and the fibres of cubing are the cosets
$\{r,\omega r,\omega^2 r\}$.
\end{proof}

\begin{lemma}[No cubic has exactly two roots]\label{lem:two}
A cubic over $\FF_\ell$ whose associated Weierstrass curve is nonsingular has $0$, $1$ or $3$
roots in $\FF_\ell$; the count $2$ is impossible.
\end{lemma}

\begin{proof}[Proof sketch]
Two distinct roots of a monic cubic split off two linear factors, leaving a third linear
factor; so exactly two distinct roots forces a repeated root, which for $T^3+N$ with
$N \not\equiv 0$ contradicts the nonvanishing of the discriminant $-27N^2$.
\end{proof}

Finally, if $A/B$ is a fraction of integers with $B \ne 0$ and a prime $\ell$ divides $B$ but
not $A$, then $\ell \mid \den(A/B)$; conversely $\den(A/B)$ always divides $B$.

\section{Layer 2: doubling}

\begin{theorem}[Doubling criterion]\label{thm:double}
Let $(x,y)$ be an integral point of $E_N$ with $y \ne 0$, and let $\ell \ge 5$ be a prime with
$\ell \nmid N$. Then
\[
\ell \;\Big|\; \den\!\left(\frac{x^4 - 8Nx}{4y^2}\right)
\iff \ell \mid y \iff \bar x^3 + \bar N = 0 \text{ in } \FF_\ell .
\]
\end{theorem}

\begin{proof}[Proof sketch]
The second equivalence is the curve equation reduced modulo $\ell$. For the first, $\den$
divides $4y^2$, so $\ell \mid \den$ implies $\ell \mid 4y^2$ and, as $\ell \ge 5$,
$\ell \mid y$. Conversely, if $\ell \mid y$ then $x^3 \equiv -N$; if $\ell \mid x$ then
$\bar N = 0$, excluded; and $x^3 - 8N \equiv -9N \not\equiv 0$ since $\ell \ge 5$,
$\ell \nmid N$. So $\ell \nmid x^4 - 8Nx = x(x^3-8N)$ while $\ell \mid 4y^2$, whence
$\ell \mid \den$.
\end{proof}

The hypothesis $\ell \ge 5$ is genuine: the constants $4$ and $-9N$ are supported on
$\{2,3\}$, the primes visible in $-432 = -2^4 3^3$.

\begin{definition}
The \emph{layer-2 vanishing locus} is
$V_2(N,\ell) = \{ t \in \FF_\ell : t^3 + \bar N = 0\}$.
\end{definition}

By Theorem~\ref{thm:double}, for good $\ell \ge 5$ an integral point $(x,y)$ with $y \ne 0$ has
$\ell \mid \den x(2P)$ if and only if $\bar x \in V_2(N,\ell)$: denominator production at the
doubling layer is exactly the event ``$\bar x$ is the $x$-coordinate of a $2$-torsion point of
the reduced curve''.

\begin{theorem}[Supersingular count]\label{thm:ss2}
If $\ell \equiv 2 \pmod 3$ then $\# V_2(N,\ell) = 1$ for every $N$.
\end{theorem}

\begin{proof}
Cubing is bijective (Lemma~\ref{lem:cube}), so $t^3 = -\bar N$ has exactly one solution.
\end{proof}

\begin{theorem}[Ordinary count]\label{thm:ord2}
If $\ell \ge 5$, $\ell \equiv 1 \pmod 3$ and $\ell \nmid N$, then
$\#V_2(N,\ell) \in \{0,3\}$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:two} the count is $0$, $1$ or $3$. If it were $1$, with unique root $r$, then
$\omega r$ is also a root ($\omega$ a primitive cube root of unity), so $\omega r = r$, hence
$r = 0$ and $\bar N = 0$, contradicting $\ell \nmid N$.
\end{proof}

\begin{theorem}[Exact average]\label{thm:avg2}
For every prime $\ell$, $\ \sum_{c \in \FF_\ell} \#V_2(c,\ell) = \ell$; the average number of
denominator-producing classes over residues of $N$ is exactly $1$.
\end{theorem}

\begin{proof}
Count pairs $(c,t)$ with $t^3 + c = 0$ in two ways: for each of the $\ell$ values of $t$ there
is exactly one $c$, namely $c = -t^3$.
\end{proof}

\begin{example}\label{ex:55}
For $N = 55$: $V_2(55,7) = \{1,2,4\}$ and $9 \equiv 2 \pmod 7$ lies in it --- this is
Theorem~\ref{thm:counterexample}. By contrast $V_2(55,13) = \varnothing$, so $13$ can never divide $\den x(2P)$ for
any integral point of $E_{55}$.
\end{example}

\section{Layer 3: tripling}

\begin{theorem}[Tripling formula]\label{thm:triple}
Let $(x,y)$ be a rational point of $E_N$ with $y \ne 0$ and $\psi_3(x) := 3x^4 + 12Nx \ne 0$.
Then
\[
x(3P) = \frac{\varphi_3(x)}{\psi_3(x)^2}, \qquad
\varphi_3(x) = x^9 - 96Nx^6 + 48N^2x^3 + 64N^3 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Two applications of the affine group law. Doubling with slope $\lambda = 3x^2/(2y)$ gives
\[
x_2 = \lambda^2 - 2x = x - \frac{3x^4+12Nx}{4y^2}, \qquad
y_2 = y - \frac{16y^4 - 3x^2\psi_3(x)}{8y^3},
\]
the simplification of $x_2$ using $y^2 = x^3+N$. Since $\psi_3(x) \ne 0$ we have $x_2 \ne x$,
so $3P = 2P + P$ is computed with the chord slope
$\mu = (y_2-y)/(x_2-x) = \bigl(16y^4 - 3x^2\psi_3(x)\bigr)/\bigl(2y\,\psi_3(x)\bigr)$, and
$x(3P) = \mu^2 - x_2 - x$. Expanding, substituting $y^2 = x^3+N$ and clearing denominators
gives $\varphi_3(x)/\psi_3(x)^2$.
\end{proof}

Here $\psi_3(x) = 3x(x^3+4N)$ is the third division polynomial: its roots are the
$x$-coordinates of the $3$-torsion points, so $\psi_3(x) \ne 0$ says precisely that $P$ is not
$3$-torsion.

\begin{theorem}[Non-cancellation at layer 3]\label{thm:noncancel}
Let $\ell \ge 5$ be a prime with $\ell \nmid N$, and let $x \in \ZZ$ satisfy
$\ell \mid \psi_3(x)$. Then $\ell \nmid \varphi_3(x)$.
\end{theorem}

\begin{proof}
Modulo $\ell$, $3\bar x(\bar x^3 + 4\bar N) = 0$ with $3 \ne 0$ since $\ell \ge 5$.
If $\bar x = 0$ then $\varphi_3(x) \equiv 64\bar N^3$, nonzero because $64 = 2^6$ and
$\bar N \ne 0$. If $\bar x^3 = -4\bar N$ then $\bar x^6 = 16\bar N^2$ and
$\bar x^9 = -64\bar N^3$, so
\[
\varphi_3(x) \equiv -64\bar N^3 - 96\bar N \cdot 16\bar N^2 + 48\bar N^2(-4\bar N)
+ 64\bar N^3 = -1728\,\bar N^3,
\]
nonzero because $1728 = 2^6 3^3$ and $\ell \ge 5$.
\end{proof}

The exceptional constants $64 = 2^6$ and $1728 = 2^6 3^3$ are exactly the small bad primes of
the Mordell family; they are why the hypothesis $\ell \ge 5$ is needed and why no further
hypothesis is.

\begin{theorem}[Tripling criterion]\label{thm:crit3}
Let $(x,y)$ be an integral point of $E_N$ with $y \ne 0$ and $\psi_3(x) \ne 0$, and let
$\ell \ge 5$ be a prime with $\ell \nmid N$. Then
\[
\ell \mid \den x(3P) \iff \ell \mid \psi_3(x) = 3x(x^3+4N).
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:triple}, $x(3P) = \varphi_3(x)/\psi_3(x)^2$. If $\ell \mid \den$ then
$\ell \mid \psi_3(x)^2$, hence $\ell \mid \psi_3(x)$. Conversely if $\ell \mid \psi_3(x)$ then
$\ell \mid \psi_3(x)^2$ and $\ell \nmid \varphi_3(x)$ by Theorem~\ref{thm:noncancel}, so
$\ell$ survives into the reduced denominator.
\end{proof}

\begin{corollary}[Layers 2 and 3 together]
Under the hypotheses above, for a prime $\ell \ge 5$ with $\ell \nmid N$,
\[
\ell \mid \den x(2P) \ \text{ or } \ \ell \mid \den x(3P) \iff \ell \mid y\,\psi_3(x).
\]
The good violating primes of the first two nontrivial layers are exactly the prime divisors
$\ge 5$ of the single integer $y\,(3x^4+12Nx)$ that do not divide $N$.
\end{corollary}

\begin{definition}
The \emph{layer-3 vanishing locus} is
$V_3(N,\ell) = \{t \in \FF_\ell : 3t^4 + 12\bar N t = 0\}$. For $\ell \ge 5$ this equals
$\{0\} \cup \{t : t^3 + 4\bar N = 0\}$.
\end{definition}

\begin{theorem}\label{thm:count3}
Let $\ell \ge 5$ with $\ell \nmid N$. If $\ell \equiv 2 \pmod 3$ then $\#V_3(N,\ell) = 2$,
namely $t = 0$ and the unique cube root of $-4\bar N$. If $\ell \equiv 1 \pmod 3$ then
$\#V_3(N,\ell) \in \{1,4\}$.
\end{theorem}

\begin{proof}[Proof sketch]
$V_3 = \{0\} \sqcup V_2(4N,\ell)$ disjointly, since $0 \in V_2(4N,\ell)$ would force
$4\bar N = 0$. Apply Theorems~\ref{thm:ss2} and~\ref{thm:ord2} to $4N$.
\end{proof}

\begin{theorem}[The two layers are disjoint]
For $\ell \ge 5$ supersingular with $\ell \nmid N$,
$\#\bigl(V_2(N,\ell) \cup V_3(N,\ell)\bigr) = 3$, the classes being the cube root of
$-\bar N$, the class $0$, and the cube root of $-4\bar N$.
\end{theorem}

\begin{proof}
If $t \in V_2 \cap V_3$ then either $t = 0$, forcing $\bar N = 0$, or $t^3 = -\bar N$ and
$t^3 = -4\bar N$, forcing $3\bar N = 0$; both are excluded. Add $1+2$.
\end{proof}

Geometrically these three classes are exactly the reductions landing on $2$- or $3$-torsion.

\begin{theorem}[Layer-3 average]
For $\ell \ge 5$, $\ \sum_{c \in \FF_\ell} \#V_3(c,\ell) = 2\ell - 1$, so the average layer-3
class count is exactly $2 - 1/\ell$.
\end{theorem}

\begin{proof}[Proof sketch]
Each of the $\ell$ residues contributes the free root $0$; the roots of $T^3+4c$ contribute
$\sum_c \#V_2(4c,\ell) = \ell$ by Theorem~\ref{thm:avg2}, minus one overlap at $c = 0$.
\end{proof}

\begin{example}
For $N = 55$, $P = (9,28)$: $\psi_3(9) = 25623 = 3^3 \cdot 13 \cdot 73$ and
$\den x(3P) = 3^6 \cdot 13^2 \cdot 73^2$. The good primes $13$ and $73$ appear; the bad primes
$5$ and $11$ do not. Note $13$ was inactive at layer $2$ (Example~\ref{ex:55}): each layer has
its own polynomial and its own classes.
\end{example}

\section{Dual densities: how many $N$ are active?}

\begin{definition}
$A_n(\ell) = \{c \in \FF_\ell : V_n(c,\ell) \ne \varnothing\}$.
\end{definition}

\begin{theorem}
If $\ell \equiv 2 \pmod 3$ then $A_2(\ell) = \FF_\ell$: every residue is active already at
layer $2$.
\end{theorem}

\begin{theorem}
If $\ell \ge 5$ and $\ell \equiv 1 \pmod 3$ then $3\,\#A_2(\ell) = \ell + 2$, i.e.\
$\#A_2(\ell) = (\ell+2)/3$, a density of exactly $\tfrac13 + \tfrac{2}{3\ell}$; dually exactly
$2(\ell-1)/3$ residues are blind, characterised by ``$-c$ is not a cube modulo $\ell$''.
\end{theorem}

\begin{proof}[Proof sketch]
$\sum_c \#V_2(c,\ell) = \ell$; the residue $c = 0$ contributes $1$ and every other active
residue contributes $3$, so $\ell = 1 + 3(\#A_2(\ell)-1)$.
\end{proof}

\begin{theorem}[No blind spots at layer 3]
For every prime $\ell$ and every residue $c$, $0 \in V_3(c,\ell)$; hence
$A_3(\ell) = \FF_\ell$ for every $\ell$.
\end{theorem}

Thus layer $3$ is uniformly productive where layer $2$ has a positive proportion of blind
spots: at ordinary primes $\#A_3(\ell) = \ell > (\ell+2)/3 = \#A_2(\ell)$.

\section{Realisation and infinitude}

\begin{theorem}[Every prime occurs]
For every prime $\ell \ge 5$ there exist $N$ and an integral point $(x,y)$ of $E_N$ with
$y \ne 0$, $\psi_3(x) \ne 0$, such that $\ell \nmid \Delta(E_N)$ and $\ell \mid \den x(3P)$.
An explicit witness is $N = 1-\ell^3$, $P = (\ell,1)$.
\end{theorem}

\begin{proof}
$1^2 = \ell^3 + (1-\ell^3)$, so $P \in E_N(\QQ)$. Modulo $\ell$, $N \equiv 1$, so
$\ell \nmid N$ and hence $\ell \nmid \Delta = -432N^2$. Also
$\psi_3(\ell) = \ell(3\ell^3 + 12 - 12\ell^3) = \ell(12 - 9\ell^3) \ne 0$ is a multiple of
$\ell$. Apply Theorem~\ref{thm:crit3}.
\end{proof}

\begin{theorem}[Infinitely many active good primes]
For every $N$, every prime $\ell \equiv 2 \pmod 3$ is denominator-active at layer $2$. By
Dirichlet's theorem there are infinitely many such primes, of natural density $1/2$; all those
with $\ell \ge 5$, $\ell \nmid N$ are primes of good reduction.
\end{theorem}

\begin{theorem}[Violations from a single doubling]
For a fixed integral point $(x,y)$ with $y \ne 0$, the good primes violating the ``only bad
primes'' conjecture at $2P$ are exactly the primes $\ell \ge 5$ dividing $y$ and not $N$; if
$k$ is their number then $5^k \le |y|$, so a single doubling exhibits at most $\log_5|y|$
violations.
\end{theorem}

\section{The information barrier}

\begin{lemma}[Locality]\label{lem:local}
Let $N,M,x \in \ZZ$ and let $\ell$ be a prime with $\ell \mid N-M$. Then
\[
\ell \mid x^3+N \iff \ell \mid x^3+M, \qquad
\ell \mid 3x^4+12Nx \iff \ell \mid 3x^4+12Mx .
\]
Consequently $V_2(N,\ell) = V_2(M,\ell)$ and $V_3(N,\ell) = V_3(M,\ell)$ whenever
$N \equiv M \pmod \ell$.
\end{lemma}

\begin{proof}
$(x^3+N)-(x^3+M) = N-M$ and $(3x^4+12Nx)-(3x^4+12Mx) = 12x(N-M)$, both divisible by $\ell$.
\end{proof}

\begin{lemma}\label{lem:dirichlet}
Let $B,n \in \NN$ and let $N$ be coprime to $B!$. Then there is a prime $M > n$ with
$M \equiv N \pmod{B!}$.
\end{lemma}

\begin{proof}[Proof sketch]
Coprimality makes $N$ a unit modulo $B!$; Dirichlet's theorem provides infinitely many primes
in its class, and one picks one exceeding $n$.
\end{proof}

\begin{lemma}\label{lem:coprime}
If $p,q$ are primes with $p,q > B$ then $\gcd(pq, B!) = 1$.
\end{lemma}

\begin{theorem}[Denominator data below $B$ cannot detect compositeness]\label{thm:barrier}
Let $B \in \NN$ and let $N = pq$ be a semiprime with $p,q$ prime and $p,q > B$. Then there is a
prime $M > N$ such that for every prime $\ell \le B$ and every $x \in \ZZ$,
\[
\ell \mid x^3+N \iff \ell \mid x^3+M, \qquad
\ell \mid 3x^4+12Nx \iff \ell \mid 3x^4+12Mx .
\]
Equivalently, $V_2(N,\ell) = V_2(M,\ell)$ and $V_3(N,\ell) = V_3(M,\ell)$ for every prime
$\ell \le B$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:coprime}, $N$ is coprime to $B!$; by Lemma~\ref{lem:dirichlet} there is a
prime $M > N$ with $M \equiv N \pmod{B!}$. For a prime $\ell \le B$ we have $\ell \mid B!$,
hence $M \equiv N \pmod \ell$, and Lemma~\ref{lem:local} applies.
\end{proof}

\begin{corollary}
The layer-2 and layer-3 denominator profile of $E_N$ restricted to primes $\ell \le B$ is
identical for the semiprime $N$ and for the prime $M$. No algorithm reading only this data can
distinguish $N$ from a prime, and a fortiori none can output $p$ or $q$.
\end{corollary}

\begin{remark}
The barrier is a statement about which primes one is willing to test. To extract factorisation
information from denominators one must use primes $\ell$ comparable in size to $p$ and $q$
themselves --- at which point trial division has already succeeded. The theorem does not say
that no factoring information exists in the arithmetic of $E_N$; it says that none exists in
the layer-2/layer-3 denominator profile below $B$.
\end{remark}

\begin{example}
Take $N = 17 \cdot 19 = 323$ and $B = 13$. Then $13! = 6\,227\,020\,800$ and
$M = 6\,227\,021\,123$ is prime with $M \equiv 323 \pmod{13!}$. One checks
$V_2(N,5) = V_2(M,5) = \{3\}$, $V_2(N,7) = V_2(M,7) = \{3,5,6\}$,
$V_2(N,11) = V_2(M,11) = \{6\}$, $V_2(N,13) = V_2(M,13) = \varnothing$, and likewise for $V_3$
at every $\ell \le 13$.
\end{example}

\section{Algorithms and numerical data}

\subsection{Verifying the criteria}
Given $N$, an integral point $(x,y)$ and a bound $L$: compute
$D_2 = \den\bigl((x^4-8Nx)/(4y^2)\bigr)$ and $D_3 = \den\bigl(\varphi_3(x)/\psi_3(x)^2\bigr)$
in exact rational arithmetic; for each prime $5 \le \ell \le L$ with $\ell \nmid N$ test
$\ell \mid y$ and $\ell \mid \psi_3(x)$; assert equality with $\ell \mid D_2$, resp.\
$\ell \mid D_3$. For $N = 55$, $P = (9,28)$, $L = 200$ every good prime satisfies both
equivalences; the only active primes are $7$ (layer $2$) and $13,73$ (layer $3$).

\subsection{Computing the loci}
$V_2$ and $V_3$ are computed by evaluating $t^3+N$ and $3t^4+12Nt$ for $t = 0,\dots,\ell-1$:
cost $O(\ell)$ per prime, $O(\ell^2)$ for a sweep over all residues of $N$, which confirms
$\sum_c \#V_2 = \ell$ and $\sum_c \#V_3 = 2\ell-1$ for all $\ell \le 100$.

\subsection{Constructing barrier twins}
Given $N$ and $B$ with $\gcd(N,B!) = 1$, iterate $M = N + kB!$ for $k = 1,2,\dots$, testing
primality with a deterministic Miller--Rabin test. In practice a handful of trials suffices;
for $N = 323$, $B = 13$ the first success is $k = 1$.

